            // Remove styling from all dropzones
            document.querySelectorAll('.dropzone').forEach(dz => dz.classList.remove('dragover'));

            // Ensure we are dropping into the dropzone div, not inside another card
            let target = ev.target;
            while (target != null && !target.classList.contains('dropzone')) {
                target = target.parentNode;
            }

            if (target && draggedElement) {
                target.appendChild(draggedElement);
            }
