                        level: index + 1,
                        cards: Array.from(cards).map(c => ({
                            type: c.querySelector('.card-type').innerText.toLowerCase(),
                            text: c.querySelector('.card-text').innerText
                        }))
                    };
                    activeRungs.push(rungData);
                }
            });

