            let holds = true;
            let feedback = [];

            // Rule 1: Top rung must have a Claim
            const topRungCards = activeRungs[0].cards;
            const hasTopClaim = topRungCards.some(c => c.type === 'claim');
            if (!hasTopClaim && activeRungs[0].level === 1) {
                holds = false;
                feedback.push("- Collapse: The top rung must contain your primary Claim.");
            } else if (!hasTopClaim) {
                holds = false;
                feedback.push("- Collapse: You are missing a main Claim at the very top (Rung 1).");
            }

            // Rule 2: Bottom-most populated rung must be Evidence or Experiment
            const bottomRungCards = activeRungs[activeRungs.length - 1].cards;
            const hasSolidFoundation = bottomRungCards.some(c => c.type === 'evidence' || c.type === 'experiment');
            if (!hasSolidFoundation) {
                holds = false;
                feedback.push("- Collapse: Your ladder lacks foundation. The bottom-most level must rest on hard Evidence or an Experiment.");
            }

            // Rule 3: Assumptions must not sit directly on the ground without support below them
            // (Covered by Rule 2, but we can check if there are floating assumptions with gaps)

            if (holds) {
                banner.className = 'result-banner result-success';
                banner.innerHTML = "✅ LADDER HOLDS.<br>Your plan rests on first principles and solid foundation.";
                receiptString += "RESULT: VALIDATED - Structure is logically sound.\n\n";
            } else {
                banner.className = 'result-banner result-fail';
                banner.innerHTML = "❌ LADDER COLLAPSES.<br>" + feedback.join('<br>');
                receiptString += "RESULT: FAILED - Structure collapsed due to logical gaps.\n";
                feedback.forEach(f => { receiptString += `${f}\n`; });
                receiptString += "\n";
            }

            banner.style.display = 'block';

            // Build Receipt Output
            receiptString += "--- STRUCTURE ---\n";
            activeRungs.forEach(rung => {
                receiptString += `[RUNG ${rung.level}]\n`;
                rung.cards.forEach(card => {
                    receiptString += `  -> ${card.type.toUpperCase()}: "${card.text}"\n`;
                });
            });

            receiptText.innerText = receiptString;
            receiptArea.style.display = 'block';
        }

        // Export Functions
        function copyReceipt() {
            const text = document.getElementById('receiptText').innerText;
            navigator.clipboard.writeText(text).then(() => {
                alert("Receipt copied to clipboard!");
            });
        }

        function downloadReceipt() {
            const text = document.getElementById('receiptText').innerText;
            const blob = new Blob([text], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'reasoning-receipt.txt';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }
    </script>
</body>
</html>

