            const bottomRungCards = activeRungs[activeRungs.length - 1].cards;
            const hasSolidFoundation = bottomRungCards.some(c => c.type === 'evidence' || c.type === 'experiment');
            if (!hasSolidFoundation) {
                holds = false;
                feedback.push("- Collapse: Your ladder lacks foundation. The bottom-most level must rest on hard Evidence or an Experiment.");
            }

            const headerDiv = document.createElement('div');

            if (holds) {
                banner.className = 'result-banner result-success';
                headerDiv.textContent = "✅ LADDER HOLDS.";
                banner.appendChild(headerDiv);

                const detailDiv = document.createElement('div');
                detailDiv.textContent = "Your plan rests on first principles and solid foundation.";
                banner.appendChild(detailDiv);

                receiptString += "RESULT: VALIDATED - Structure is logically sound.\n\n";
            } else {
                banner.className = 'result-banner result-fail';
                headerDiv.textContent = "❌ LADDER COLLAPSES.";
                banner.appendChild(headerDiv);

                feedback.forEach(f => {
                    const failDetail = document.createElement('div');
                    failDetail.textContent = f;
                    banner.appendChild(failDetail);
                    receiptString += `${f}\n`;
                });

                receiptString = "RESULT: FAILED - Structure collapsed due to logical gaps.\n" + receiptString + "\n";
            }

            banner.style.display = 'flex';

            // Build Receipt Output
            receiptString += "--- STRUCTURE ---\n";
            activeRungs.forEach(rung => {
                receiptString += `[RUNG ${rung.level}]\n`;
                rung.cards.forEach(card => {
                    receiptString += `  -> ${card.type.toUpperCase()}: "${card.text}"\n`;
                });
            });

            receiptText.textContent = receiptString;
            receiptArea.style.display = 'block';
        }

        // Export Functions
        function copyReceipt() {
            const text = document.getElementById('receiptText').textContent;
            const statusDiv = document.getElementById('copyStatus');

            navigator.clipboard.writeText(text).then(() => {
                statusDiv.textContent = "Copied!";
                setTimeout(() => {
                    statusDiv.textContent = "";
                }, 2000);
            }).catch(err => {
                statusDiv.textContent = "Failed";
                statusDiv.style.color = "#e74c3c";
            });
        }

        function downloadReceipt() {
            const text = document.getElementById('receiptText').textContent;
            const blob = new Blob([text], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = 'reasoning-receipt.txt';
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
        }
    </script>
